import { useEffect,useState } from 'react'
import api from '../../services/api'
import LoadingSpinner from '../../components/LoadingSpinner'
export default function VendorStore(){const [form,setForm]=useState(null);const [message,setMessage]=useState('');useEffect(()=>{api.get('/api/vendor/store').then(({data})=>setForm(data)).catch(()=>setForm({business_name:'',business_type:'OTHER',description:'',phone:'',email:'',address:'',area:'',city:'',state:'',pincode:'',is_active:true}))},[]);if(!form)return <LoadingSpinner/>;function update(e){setForm({...form,[e.target.name]:e.target.value})}async function save(e){e.preventDefault();await api.patch('/api/vendor/store',form);setMessage('Store updated successfully.')}return <><span className="section-kicker">Vendor workspace</span><h1 className="vendor-title">Manage Store</h1>{message&&<div className="form-success">{message}</div>}<form className="vendor-form" onSubmit={save}>{['business_name','description','phone','email','address','area','city','state','pincode'].map(name=><label key={name}>{name.replace('_',' ')}{name==='description'?<textarea name={name} value={form[name]} onChange={update}/>:<input name={name} value={form[name]} onChange={update} required/>}</label>)}<label className="toggle"><input type="checkbox" checked={form.is_active} onChange={e=>setForm({...form,is_active:e.target.checked})}/> Store open and visible</label><button className="auth-submit">Save Store</button></form></>}
